import {showDocument,closeReader} from './document-reader.js';
import {syncAccount,pauseSync,flushProgress} from './progress-sync.js';
import {store,escape as e,download} from './store.js';
import * as seed from './data.js';
import {backend} from './backend.js';
import {forgotPage,resetPage,bindRecovery,handleRecoveryLink} from './recovery.js';
import {trackVisit} from './analytics.js';
import {loadAbout,aboutPage,supportPage} from './about.js';
import {subjectCatalog} from './subjects.js';
import {initAdmin,resetAdmin,loadAdmin,renderAdmin,bindAdmin,adminClick} from './admin.js';
import {initAudio,playRecording,isAudioRecording,syncAudioButtons,stopAudio} from './audio.js';
import {initDownloads,requestDownload} from './downloads.js';
const $=s=>document.querySelector(s);
const paths={dashboard:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',materials:'M4 3h12l4 4v14H4zM15 3v5h5M8 12h8M8 16h6',lectures:'M3 5h18v14H3zM10 9l5 3-5 3z',quiz:'M9 3h6v4H9zM8 5H5v16h14V5h-3M8 12h8M8 16h5',cases:'M12 3v18M6 21h12M4 7h16M6 7l-4 8h8L6 7zm12 0-4 8h8l-4-8z',study:'M12 8v5l3 2M9 2h6M12 2v3M20 5l-2 2M12 5a8 8 0 1 0 0 16 8 8 0 0 0 0-16',flashcards:'M5 6h16v15H5zM2 18V3h16',progress:'M4 21V12M10 21V7M16 21V3M2 21h20',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M14 7l5 5-5 5',calendar:'M4 5h16v16H4zM4 9h16M8 2v6M16 2v6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',bookmark:'M6 3h12v18l-6-4-6 4z'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const routes={dashboard:'Dashboard',materials:'Materials',lectures:'Lecture Recordings',quiz:'Quizzes',cases:'CaseVault',study:'Study Mode',flashcards:'Flashcards',progress:'My Progress',settings:'Settings',studio:'Content Studio',support:'Contact & Support',about:'About LexAmah',admin:'Admin Dashboard',signup:'Sign Up',login:'Log In',forgot:'Password Recovery',reset:'Reset Password'};
let route='dashboard',filter='',subject='All subjects',remote={},flashIndex=0,flashBack=false,quiz=null,quizTimer=null,focusTimer=null,focusSeconds=1500,focusRemaining=1500,focusRunning=false,focusEnd=0,focusSubject='Legal Methods',materialKind='all';
let toastTimer,accessChecked=false,accessFlight=null,accountEpoch=0;
const publicRoutes=new Set(['login','signup','forgot','reset','about','support']);
let sidebarCollapsed=localStorage.getItem('lexamah:sidebar-collapsed')==='true';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function modal(title,body){$('#dialog-content').innerHTML=`<h2>${e(title)}</h2>${body}`;$('#dialog').showModal();}
function list(type){return [...(seed[type]||[]),...(store.get()[type]||[]),...(remote[type]||[])].filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);}
function button(text,to,cls=''){return `<button class="btn ${cls}" data-route="${to}">${text} ${icon('arrow')}</button>`;}
function heading(title,description,action=''){return `<div class="heading"><div><span class="eyebrow">YOUR LEGAL LEARNING SPACE</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon">§</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function toolbar(type){return `<div class="toolbar"><input id="search" aria-label="Search ${type}" placeholder="Search ${type}…" value="${e(filter)}"><select id="subject" aria-label="Filter by subject">${subjectCatalog.filters().map(s=>`<option ${s===subject?'selected':''}>${e(s)}</option>`).join('')}</select></div>`;}
function filtered(items){return items.filter(x=>(subject==='All subjects'||x.subject===subject)&&`${x.title||x.name||x.front} ${x.description||''} ${x.subject||''}`.toLowerCase().includes(filter.toLowerCase()));}
function today(){return new Date().toLocaleDateString('en-CA');}
function minutes(){return store.get().sessions.reduce((s,x)=>s+x.minutes,0);}
function score(){const a=store.get().attempts;return a.length?Math.round(a.reduce((s,x)=>s+x.score/x.total_questions*100,0)/a.length):0;}
function stats(){const s=store.get();return `<div class="stats">${[[s.completed.length,'Materials completed','Your reading journey','materials'],[s.attempts.length,'Quizzes completed',s.attempts.length?`${score()}% average score`:'Put your knowledge to work','quiz'],[minutes(),'Focus minutes','Make every session count','study'],[s.bookmarks.length,'Saved resources','Ready when you need them','bookmark']].map(([n,t,sub,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><small>${t}</small><strong>${n}</strong><span class="sub">${sub}</span></div></div>`).join('')}</div>`;}
function dashboard(){const s=store.get();const tasks=s.tasks;return heading(`A good day to learn, ${e(s.profile.name.split(' ')[0])}.`,'A little focus today. A stronger advocate tomorrow.',`<span class="date">${icon('calendar')}${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span>`)+`<section class="hero"><div><span class="eyebrow">YOUR AMBITION. YOUR WORKSPACE.</span><h2>Build your knowledge.<br>Find your legal voice.</h2><p>Your materials, authorities and revision tools, thoughtfully brought together for the journey ahead.</p>${button('Start a focused session','study')}</div><div class="hero-art" aria-hidden="true"><span>§</span></div></section>${stats()}<div class="dashboard-grid"><div><section class="card"><div class="card-head"><div><h2>Your next chapter</h2><p>A thoughtful place to begin your study session</p></div><button class="text-button" data-route="materials">All materials ↗</button></div>${list('materials').slice(0,3).map((m,i)=>`<div class="row"><span class="row-icon">${['▤','▥','▧'][i]}</span><div class="row-copy"><strong>${e(m.title)}</strong><small>${e(m.subject)} <span class="dot">·</span> ${e(m.type||'Resource')}</small></div><button class="btn" data-open-material="${e(m.id)}">${s.completed.includes(m.id)?'Revisit':'Read'} ↗</button></div>`).join('')}</section><section class="card" style="margin-top:22px"><div class="card-head"><h2>Latest Lecture Recordings</h2><button class="text-button" data-route="lectures">View all ↗</button></div>${recordings().length?recordingRows(recordings().slice(0,3)):'<p class="muted">Audio recordings uploaded by your administrator will appear here.</p>'}</section><div class="section-title"><h2>Make your next move</h2><span class="muted">Study your way</span></div><div class="quick-grid">${[['quiz','Test your knowledge','Practice. Review. Improve.'],['cases','Explore CaseVault','Keep authorities in order.'],['flashcards','Quick recall','Small cards. Lasting learning.']].map(([r,t,d])=>`<button class="quick" data-route="${r}">${icon(r)}<strong>${t}</strong><small>${d}</small></button>`).join('')}</div></div><div><section class="card"><div class="card-head"><h2>Today’s intention</h2><span class="pill">${tasks.filter(t=>t.done).length}/${tasks.length}</span></div><p class="muted">Turn your to-do list into a little progress.</p><div>${tasks.length?tasks.map(t=>`<label class="task ${t.done?'completed':''}"><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''}><span>${e(t.text)}</span><button class="remove-task" data-remove-task="${e(t.id)}" aria-label="Remove task">×</button></label>`).join(''):'<p class="muted">Add your first study intention below.</p>'}</div><form id="task-form" class="task-add"><input name="task" required maxlength="160" placeholder="What will you learn today?" aria-label="New study task"><button class="btn soft" aria-label="Add task">+</button></form></section><section class="focus-mini"><span class="eyebrow">A MOMENT OF FOCUS</span><h3>One topic. Full attention.</h3><p>Set aside 25 minutes. Silence the noise and make room for something worth learning.</p>${button('Enter Study Mode','study','primary')}</section></div></div>`;}
function readingItems(){return [...list('materials').map(x=>({...x,resource_type:'materials'})),...list('lectureNotes').map(x=>({...x,resource_type:'lectureNotes'}))];}
function recordings(){return (remote.lectures||[]).filter(isAudioRecording);}
function materials(){return heading('Materials & Lecture Notes','Read your course resources and download them with your access code.')+`<div class="admin-tabs">${[['all','All resources'],['materials','Materials'],['lectureNotes','Lecture notes']].map(([kind,label])=>`<button class="btn ${materialKind===kind?'primary':''}" data-reading-kind="${kind}">${label}</button>`).join('')}</div>`+toolbar('materials and lecture notes')+`<div class="grid" id="results">${materialCards()}</div>`;}

function materialCards(){const state=store.get(),items=filtered(readingItems()).filter(x=>materialKind==='all'||x.resource_type===materialKind);return items.length?items.map(m=>`<article class="card resource"><div class="resource-top"><span class="tag">${e(m.subject||'General')}</span><button class="icon-button" data-bookmark="${e(m.id)}" aria-label="${state.bookmarks.includes(m.id)?'Unsave':'Save'} ${e(m.title)}">${state.bookmarks.includes(m.id)?'◆':'◇'}</button></div><h3>${e(m.title)}</h3><p>${e(m.description||'Course resource')}</p><span class="muted">${m.resource_type==='lectureNotes'?'Lecture note':'Material'}</span><div class="actions"><button class="btn primary" data-open-resource="${m.resource_type}:${e(m.id)}">Read notes</button><button class="btn" data-download-resource="${m.resource_type}:${e(m.id)}">Download ↓</button>${state.completed.includes(m.id)?'<span class="tag">Completed ✓</span>':''}</div></article>`).join(''):empty('No matching resources.','Choose another subject or check back for new resources.');}

function recordingRows(items){return items.map(record=>`<div class="row"><span class="row-icon">♫</span><div class="row-copy"><strong>${e(record.title)}</strong><small>${e(record.subject)} · Audio recording</small></div><button class="btn primary" data-play-recording="${e(record.id)}" aria-pressed="false">▶ Play</button></div>`).join('');}
function lectures(){const items=filtered(recordings());return heading('Lecture Recordings','Listen to audio recordings uploaded by your course administrator.')+toolbar('lecture recordings')+`<div id="results" class="grid">${items.length?items.map(record=>`<article class="card resource"><span class="tag">${e(record.subject)}</span><h3>${e(record.title)}</h3><p>${e(record.description||'Audio lecture recording')}</p><div class="actions"><button class="btn primary" data-play-recording="${e(record.id)}" aria-pressed="false">▶ Play</button></div></article>`).join(''):empty('Your audio library starts here.',backend.user()?'Your administrator can upload audio recordings. They will appear here and on your dashboard.':'Log in to listen to your course recordings.',backend.user()?'':button('Log in','login','primary'))}</div>`;}

function cases(){const a=filtered(list('cases'));return heading('Authorities, thoughtfully organized.','Build a personal vault of judgments, citations and case briefs.',button('Add a case','studio','primary'))+toolbar('cases')+`<div id="results" class="grid">${a.length?a.map(c=>`<article class="card resource"><span class="tag">${e(c.subject)}</span><h3>${e(c.title||c.name)}</h3><p>${e(c.citation||c.description||'Personal case brief')}</p><div class="actions"><button class="btn primary" data-open-case="${e(c.id)}">Read brief ↗</button><button class="btn" data-bookmark="${e(c.id)}">${store.get().bookmarks.includes(c.id)?'Saved ✓':'Save'}</button></div></article>`).join(''):empty('Every argument needs a foundation.','Add verified judgments and your own case briefs. Keep facts, issues, decisions and reasoning in one place.',button('Create your first brief','studio'))}</div>`;}
function quizPage(){if(quiz?.finished)return resultsPage();if(quiz)return activeQuiz();return heading('Practice with purpose.','Test your understanding, review every answer and track your growth.')+`<div class="notice">Start with the orientation quiz, or create subject-specific questions in Content Studio.</div><div class="grid">${list('quizSets').map(q=>{const count=list('quizQuestions').filter(x=>x.quiz_set_id===q.id).length;return `<article class="card resource"><div class="resource-top"><span class="tag">${e(q.subject||'General')}</span><span class="pill">${e(q.difficulty||'Practice')}</span></div><h3>${e(q.name)}</h3><p>${e(q.description||'A focused revision challenge.')}</p><p>${count} questions <span class="dot">·</span> ${Number(q.time_minutes)||10} minutes</p><div class="actions"><button class="btn primary" data-start-quiz="${e(q.id)}" ${!count?'disabled':''}>Start quiz →</button></div></article>`;}).join('')}</div>`;}
function time(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function activeQuiz(){const q=quiz.questions[quiz.index];return heading(e(quiz.set.name),'Take your time, read carefully and choose your answer.')+`<section class="card quiz"><div class="card-head"><span class="pill">Question ${quiz.index+1} of ${quiz.questions.length}</span><span class="tag" id="quiz-clock">${time(Math.max(0,Math.ceil((quiz.end-Date.now())/1000)))}</span></div><div class="progress-track"><span style="width:${(quiz.index+1)/quiz.questions.length*100}%"></span></div><h2 class="question">${e(q.question)}</h2>${q.options.map((o,i)=>`<button class="option ${quiz.answers[quiz.index]===i?'selected':''}" data-answer="${i}" ${quiz.advancing?'disabled':''} aria-pressed="${quiz.answers[quiz.index]===i}"><span>${'ABCD'[i]}</span>${e(o)}</button>`).join('')}<div class="actions"><button class="btn" id="quiz-prev" ${!quiz.index?'disabled':''}>← Previous</button>${quiz.index<quiz.questions.length-1?'<button class="btn primary" id="quiz-next">Next question →</button>':'<button class="btn primary" id="quiz-finish">Submit quiz</button>'}<button class="text-button" id="quiz-exit">Exit quiz</button></div></section>`;}
async function finishQuiz(){if(!quiz||quiz.finished)return;clearInterval(quizTimer);quiz.finished=true;quiz.score=quiz.questions.filter((q,i)=>Number(q.correct_index)===quiz.answers[i]).length;const a={id:crypto.randomUUID(),quiz_set_id:quiz.set.id,name:quiz.set.name,score:quiz.score,total_questions:quiz.questions.length,date:new Date().toISOString()};store.update({attempts:[...store.get().attempts,a]});render();if(backend.user()&&!String(a.quiz_set_id).startsWith('local-')&&a.quiz_set_id!=='orientation'){try{await backend.saveQuizAttempt(a,Boolean(remote.quizSets?.find(s=>s.id===a.quiz_set_id)?.lexamah_cloud));toast('Result saved to your account.');}catch(err){toast(`Saved on this browser. Account sync failed: ${err.message}`);}}}
function resultsPage(){return heading('A little wiser than before.','Review your answers and take your learning forward.')+`<section class="card quiz"><span class="eyebrow">YOUR QUIZ RESULT</span><div class="score">${quiz.score}<span class="muted"> / ${quiz.questions.length}</span></div><p class="muted">${Math.round(quiz.score/quiz.questions.length*100)}% correct · Saved to your progress</p><div class="actions"><button class="btn primary" id="quiz-reset">Back to quizzes</button>${button('View progress','progress')}</div>${quiz.questions.map((q,i)=>`<div class="review"><strong>${i+1}. ${e(q.question)}</strong><p class="${quiz.answers[i]===Number(q.correct_index)?'correct':'incorrect'}">Your answer: ${e(q.options[quiz.answers[i]]||'Not answered')}</p><p>Correct answer: ${e(q.options[Number(q.correct_index)])}</p><p class="muted">${e(q.explanation||'Review this question with your course materials.')}</p></div>`).join('')}</section>`;}
function study(){return heading('Make room for focus.','One topic, one session, one step forward.')+`<section class="card timer-card"><span class="eyebrow">THE FOCUS ROOM</span><h2 style="font:30px var(--serif);margin:20px">Your next 25 minutes matter.</h2><label for="focus-subject">What are you studying?</label><select id="focus-subject" ${focusRunning?'disabled':''}>${subjectCatalog.options(focusRunning?focusSubject:'').map(s=>`<option ${s===focusSubject?'selected':''}>${e(s)}</option>`).join('')}</select><div class="timer" id="focus-clock">${time(focusRemaining)}</div><div class="timer-status" id="focus-status">${focusRunning?'FOCUS IN PROGRESS':'READY WHEN YOU ARE'}</div><div class="actions"><button class="btn primary" id="focus-toggle" ${!focusSubject?'disabled':''}>${focusRunning?'Pause session':'Start session'}</button><button class="btn" id="focus-reset">Reset</button><button class="btn" id="focus-end">Finish & save</button></div><label for="focus-length">Session length</label><select id="focus-length" ${focusRunning?'disabled':''}>${[15,25,45].map(n=>`<option value="${n}" ${focusSeconds===n*60?'selected':''}>${n} minutes</option>`).join('')}</select><p class="muted" style="margin-top:30px">Sessions are recorded only when you finish them. Keep this page open while you study.</p></section>`;}
function saveFocus(){const elapsed=Math.min(focusSeconds,focusSeconds-focusRemaining);if(elapsed<60){toast('Study for at least one minute before saving a session.');return;}clearInterval(focusTimer);focusRunning=false;store.update({sessions:[...store.get().sessions,{id:crypto.randomUUID(),subject:focusSubject,minutes:Math.floor(elapsed/60),date:new Date().toISOString()}]});focusRemaining=focusSeconds;toast('Session saved. A little progress worth celebrating.');render();}
function cards(){const a=filtered(list('flashcards'));if(flashIndex>=a.length)flashIndex=0;const c=a[flashIndex];return heading('Give your memory a little practice.','Flip, recall and repeat. Build your own deck as you learn.',`<button class="btn primary" data-create="flashcards">+ Create card</button>`)+toolbar('flashcards')+`<div id="results">${c?`<button class="flashcard" id="flip-card" aria-label="Flip flashcard"><span class="tag">${e(c.subject)}</span><strong>${e(flashBack?c.back:c.front)}</strong><span class="muted">${flashBack?'Answer · click to return':'Question · click to reveal'}</span></button><div class="flash-nav"><button class="btn" id="flash-prev">← Previous</button><span class="muted">${flashIndex+1} / ${a.length}</span><button class="btn primary" id="flash-next">Next →</button></div>`:empty('No cards in this deck.','Create your own cards or choose another subject.')}</div>`;}
function progress(){const s=store.get();const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:d.toLocaleDateString('en-CA'),label:d.toLocaleDateString('en-GB',{weekday:'short'})};});const values=days.map(d=>s.sessions.filter(x=>new Date(x.date).toLocaleDateString('en-CA')===d.key).reduce((a,x)=>a+x.minutes,0));const max=Math.max(30,...values);return heading('Look how far you’re going.','Every page, every question and every focused minute adds up.')+stats()+`<div class="two-col"><section class="card"><div class="card-head"><h2>Your week in focus</h2><span class="pill">${values.reduce((a,b)=>a+b,0)} min</span></div><div class="bar-chart">${days.map((d,i)=>`<div><span class="muted">${values[i]}</span><div class="bar" style="height:${values[i]/max*100}%" title="${d.label}: ${values[i]} minutes"></div><small>${d.label}</small></div>`).join('')}</div><p class="muted" style="margin-top:35px">Completed focus minutes over the last seven days.</p></section><section class="card"><div class="card-head"><h2>Recent study sessions</h2>${button('Study now','study')}</div>${s.sessions.length?s.sessions.slice(-5).reverse().map(x=>`<div class="row"><span class="stat-icon">${icon('study')}</span><div class="row-copy"><strong>${e(x.subject)}</strong><small>${new Date(x.date).toLocaleDateString('en-GB')}</small></div><span class="tag">${x.minutes} min</span></div>`).join(''):'<p class="muted">Complete your first focus session to see it here.</p>'}</section></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Your quiz history</h2>${button('Take a quiz','quiz')}</div>${s.attempts.length?`<div class="table-wrap"><table><thead><tr><th>QUIZ</th><th>DATE</th><th>SCORE</th><th>ACCURACY</th></tr></thead><tbody>${s.attempts.slice().reverse().map(a=>`<tr><td>${e(a.name)}</td><td>${new Date(a.date).toLocaleDateString('en-GB')}</td><td>${a.score}/${a.total_questions}</td><td><span class="tag">${Math.round(a.score/a.total_questions*100)}%</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Your completed quizzes will appear here.</p>'}</section>`;}
function applyAccountProfile(){if(!backend.user())return;const profile=backend.profile();store.update({profile:{...store.get().profile,name:profile.full_name||store.get().profile.name,username:profile.username||'',phone_number:profile.phone_number||'',email:backend.user().email||'',institution:profile.institution||'',level:profile.level||''}});}
function signup(){return heading('Your next chapter starts here.','Create your LexAmah account and organize your legal learning.')+`<section class="card auth-card"><h2>Sign up</h2><form id="signup-form"><label for="signup-name">Full name</label><input id="signup-name" name="full_name" required maxlength="70" autocomplete="name" placeholder="Adv Chimdike"><label for="signup-email">Email</label><input id="signup-email" name="email" type="email" required autocomplete="email" placeholder="AdvChimdike@gmail.com"><label for="signup-phone">Phone Number</label><input id="signup-phone" name="phone_number" type="tel" required minlength="7" maxlength="25" pattern="[+0-9 ()-]{7,25}" autocomplete="tel" placeholder="08012345678 or +2348012345678"><label for="signup-institution">Institution</label><input id="signup-institution" name="institution" required maxlength="160" placeholder="University of Port Harcourt"><label for="signup-level">Level</label><input id="signup-level" name="level" required maxlength="40" placeholder="LLB 4"><label for="signup-username">Username</label><input id="signup-username" name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_.]{3,30}" autocomplete="username" placeholder="AdvChimdike"><p class="muted">3–30 characters: letters, numbers, underscores or periods. Usernames are not case-sensitive.</p><label for="signup-password">Password</label><input id="signup-password" name="password" type="password" required minlength="8" maxlength="200" autocomplete="new-password" placeholder="Choose a password (at least 8 characters)"><p id="signup-status" class="muted" role="status"></p><div class="actions"><button class="btn primary">Create account →</button><button type="button" class="btn" data-route="login">Already registered? Log in</button></div></form></section>`;}
function login(){return heading('Welcome back.','Log in to your study workspace.')+`<section class="card auth-card"><h2>Log in</h2><form id="login-form"><label for="login-username">Username</label><input id="login-username" name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_.]{3,30}" autocomplete="username" placeholder="AdvChimdike"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required maxlength="200" autocomplete="current-password" placeholder="Enter your password"><p id="login-status" class="muted" role="status"></p><div class="actions"><button class="btn primary">Log in →</button><button class="btn" type="button" data-route="signup">Create account</button><button class="text-button" type="button" data-route="forgot">Forgot password?</button></div></form></section>`;}
function settings(){const state=store.get(),config=backend.config();return heading('A workspace that feels like yours.','Manage your profile, connection and personal study data.')+`<div class="two-col"><section class="card"><div class="card-head"><h2>Your profile</h2></div><form id="profile-form"><label for="profile-name">Full name</label><input id="profile-name" name="name" value="${e(state.profile.name)}" required maxlength="70"><label for="profile-phone">Phone Number</label><input id="profile-phone" name="phone_number" type="tel" maxlength="25" pattern="[+0-9 ()-]{7,25}" autocomplete="tel" value="${e(state.profile.phone_number||'')}"><label for="profile-institution">Institution</label><input id="profile-institution" name="institution" value="${e(state.profile.institution||'')}" maxlength="160" ${backend.user()?'required':''}><label for="profile-level">Level</label><input id="profile-level" name="level" value="${e(state.profile.level)}" maxlength="40" ${backend.user()?'required':''}>${backend.user()?`<p class="muted">Username: ${e(state.profile.username||'Not assigned')}<br>Email: ${e(backend.user().email)}</p>`:''}<div class="actions"><button class="btn primary">Save profile</button><button type="button" class="btn" id="settings-theme">Switch appearance</button></div></form></section><section class="card"><div class="card-head"><h2>Your account</h2></div>${backend.user()?`<p class="muted">Logged in as ${e(state.profile.username||state.profile.name)}</p><button class="btn" id="sign-out">Log out</button>`:`<p class="muted">Log in with your username and password, or create an account.</p><div class="actions">${button('Log in','login','primary')}${button('Sign up','signup')}</div>`}</section><section class="card"><div class="card-head"><h2>Your data, within reach</h2><span class="pill">This browser</span></div><p class="muted">Export your local progress and personal notes before changing devices.</p><div class="actions"><button class="btn primary" id="export-data">Export backup</button><label class="btn" style="margin:0" for="import-data">Import backup</label><input type="file" accept="application/json,.json" id="import-data" class="hidden"></div><div class="actions">${button('Open Content Studio','studio')}</div></section>${backend.adminReady()?`<section class="card"><div class="card-head"><h2>Account connection</h2><span class="pill">${backend.configured()?'Configured':'Key required'}</span></div><p class="muted">Project connection for this browser. Use only a public publishable or anon key.</p><form id="config-form"><label for="supabase-url">Project URL</label><input id="supabase-url" name="url" type="url" required value="${e(config.url)}"><label for="supabase-key">Publishable / anon key</label><input id="supabase-key" name="key" type="password" autocomplete="off" required value="${e(config.key)}"><div class="actions"><button class="btn primary">Save & check connection</button></div></form></section>`:""}</div>`;}
function studio(){return heading('An organized home for your content.','Create and maintain your own study library.')+`<div class="notice">Content Studio saves personal resources to this browser. These resources belong to your account and do not change the shared library.</div><div class="quick-grid">${[['materials','Study materials','Notes and resource links'],['lectureNotes','Lecture notes','Your written lecture notes'],['cases','Case briefs','Judgments and authorities'],['flashcards','Flashcards','Build a revision deck'],['quizSets','Quiz sets','A new practice challenge'],['quizQuestions','Quiz questions','Questions and explanations']].map(([type,title,desc])=>`<button class="quick" data-create="${type}">${icon(type==='quizSets'||type==='quizQuestions'?'quiz':type)}<strong>${title}</strong><small>+ ${desc}</small></button>`).join('')}</div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Your custom resources</h2><span class="pill">Browser library</span></div>${['materials','lectureNotes','cases','flashcards','quizSets','quizQuestions'].flatMap(type=>(store.get()[type]||[]).map(x=>`<div class="row"><div class="row-copy"><strong>${e(x.title||x.name||x.front||x.question)}</strong><small>${e(type)} · ${e(x.subject||'Practice')}</small></div><button class="btn" data-edit="${type}:${e(x.id)}">Edit</button><button class="btn danger" data-delete="${type}:${e(x.id)}">Delete</button></div>`)).join('')||'<p class="muted">Create your first resource above. Built-in orientation guides remain available in Materials.</p>'}</section>`;}
function render(){const expected=backend.recoveryReady()?null:backend.user()?.id||null;if(store.owner()!==expected)resetWorkspace(expected);if(!publicRoutes.has(route)&&(!backend.user()||backend.recoveryReady()))route='login';if(route==='admin'&&!backend.adminReady())route='dashboard';document.title=`${routes[route]} · LexAmah`;$('#crumb').textContent=routes[route];$('#nav').innerHTML=Object.entries(routes).filter(([k])=>!['settings','studio','signup','login','forgot','reset'].includes(k)&&(k!=='admin'||backend.adminReady())&&(backend.user()||publicRoutes.has(k))).map(([k,v])=>`<button class="nav-link ${route===k?'active':''}" data-route="${k}" ${route===k?'aria-current="page"':''}>${icon(k)}${v}</button>`).join('');$('#content').innerHTML=(!accessChecked&&backend.user()&&!publicRoutes.has(route))?'<section class="card auth-card"><h2>Checking your account…</h2></section>':({dashboard,materials,lectures,cases,quiz:quizPage,study,flashcards:cards,progress,settings,studio,signup,login,support:supportPage,about:aboutPage,forgot:forgotPage,reset:resetPage,admin:renderAdmin}[route])();document.body.classList.toggle('dark',store.get().theme==='dark');$('#user-label').innerHTML=`${e(store.get().profile.name)}<small>${e(store.get().profile.level)}</small>`;document.querySelectorAll('.avatar').forEach(x=>x.textContent=store.get().profile.name.slice(0,1).toUpperCase());$('#connection').textContent=backend.user()?'Account connected':'Welcome to LexAmah';document.querySelectorAll('[data-route="settings"]').forEach(el=>{el.hidden=!backend.user();});updateSidebar();bindForms();bindRecovery({toast});if(route==='admin')bindAdmin();syncAudioButtons();$('#account-links').innerHTML=backend.user()?'':`<button class="text-button" data-route="login">Log in</button><button class="btn soft" data-route="signup">Sign up</button>`;}
function navigate(){const next=location.hash.slice(1);route=routes[next]?next:'dashboard';filter='';subject='All subjects';materialKind='all';$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);if(route==='admin'&&backend.adminReady())loadAdmin();}
function safeURL(raw){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function resourceById(type,id){return list(type).find(x=>x.id===id);}
async function openResource(type,id){if(!backend.user())throw new Error('Log in to read resources.');if(['materials','lectureNotes'].includes(type)){const item=resourceById(type,id);if(item)await showDocument(item,type,{modal,onRead(){if(!store.get().completed.includes(id)){store.update({completed:[...store.get().completed,id]});render();}}});return;}const item=resourceById(type,id);if(!item)return;const notes=store.get().notes[id]||'';modal(item.title||item.name,`<span class="tag">${e(item.subject||'General')}</span>${item.citation?`<p class="muted">${e(item.citation)}</p>`:''}<div class="reader" style="margin-top:20px">${e(item.body||item.content||item.summary||item.description||'Select Download to get the attached resource.')}</div><label for="resource-notes">Your personal notes</label><textarea id="resource-notes">${e(notes)}</textarea><div class="actions"><button class="btn primary" id="save-notes">Save personal notes</button><button class="btn" id="complete-material">${store.get().completed.includes(id)?'Mark unread':'Mark completed'}</button><button class="btn" id="download-material">Download ${type==='lectureNotes'?'lecture note':'material'} ↓</button></div>`);$('#save-notes').onclick=()=>{store.update({notes:{...store.get().notes,[id]:$('#resource-notes').value}});toast('Notes saved.');};$('#complete-material').onclick=()=>{store.toggle('completed',id);$('#dialog').close();render();toast('Reading progress updated.');};$('#download-material').onclick=()=>{const text=$('#resource-notes').value;$('#dialog').close();requestDownload({...item,resource_type:type},{personalNotes:text});};}
function createForm(type,id){if(!backend.user())throw new Error('Log in first.');if(type!=='quizQuestions'&&!subjectCatalog.names().length&&!id){toast('Ask your administrator to add a subject first.');return;}if(type==='lectures'){toast('Audio recordings are added by the platform team.');return;}const x=id?store.get()[type].find(x=>x.id===id):{};const field=(name,label,value='',tag='input',extra='')=>`<label for="field-${name}">${label}</label><${tag} id="field-${name}" name="${name}" ${tag==='input'?`value="${e(value)}"`:''} ${extra}>${tag==='textarea'?e(value):''}${tag==='textarea'?'</textarea>':''}`;let body='';if(type==='flashcards')body=field('front','Question',x.front,'textarea','required')+field('back','Answer',x.back,'textarea','required');else if(type==='quizQuestions')body=`<label for="quiz-set">Quiz set</label><select name="quiz_set_id" id="quiz-set" required>${store.get().quizSets.map(q=>`<option value="${e(q.id)}" ${x.quiz_set_id===q.id?'selected':''}>${e(q.name)}</option>`).join('')}</select>`+field('question','Question',x.question,'textarea','required')+[0,1,2,3].map(i=>field(`option${i}`,`Option ${'ABCD'[i]}`,x.options?.[i]||'','input','required')).join('')+`<label for="correct-index">Correct answer</label><select id="correct-index" name="correct_index">${[0,1,2,3].map(i=>`<option value="${i}" ${Number(x.correct_index)===i?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select>`+field('explanation','Explanation',x.explanation,'textarea','required');else body=field(type==='quizSets'?'name':'title','Title',x.title||x.name,'input','required maxlength="180"')+field('description','Description',x.description,'textarea');if(type!=='quizQuestions')body+=`<label for="field-subject">Subject</label><select id="field-subject" name="subject">${subjectCatalog.options(x.subject).map(s=>`<option ${x.subject===s?'selected':''}>${e(s)}</option>`).join('')}</select>`;if(type==='materials'||type==='lectureNotes'||type==='cases')body+=field('body',type==='cases'?'Brief: facts, issues, decision and reasoning':'Resource content',x.body,'textarea');if(['materials','lectureNotes','cases'].includes(type))body+=field('url','Source / recording URL (optional)',x.url,'input','type="url"');if(type==='cases')body+=field('citation','Verified citation',x.citation);if(type==='quizSets')body+=field('time_minutes','Time limit in minutes',x.time_minutes||10,'input','type="number" min="1" max="180" required');if(type==='quizQuestions'&&!store.get().quizSets.length){toast('Create a quiz set before adding questions.');return;}modal(`${id?'Edit':'Create'} ${type.replace(/([A-Z])/g,' $1').toLowerCase()}`,`<form id="create-form">${body}<div class="actions"><button class="btn primary">Save resource</button><button type="button" class="btn" id="cancel-create">Cancel</button></div></form>`);$('#cancel-create').onclick=()=>$('#dialog').close();$('#create-form').onsubmit=ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(ev.target));if(values.url&&!safeURL(values.url)){toast('Use an HTTP or HTTPS URL.');return;}const item={...x,...values,id:id||`local-${crypto.randomUUID()}`};if(type==='quizQuestions'){item.options=[0,1,2,3].map(i=>values[`option${i}`]);item.correct_index=Number(values.correct_index);[0,1,2,3].forEach(i=>delete item[`option${i}`]);}if(type==='quizSets')item.time_minutes=Number(values.time_minutes);const items=store.get()[type];store.update({[type]:id?items.map(y=>y.id===id?item:y):[...items,item]});$('#dialog').close();render();toast('Resource saved.');};}
function toggleTheme(){store.update({theme:store.get().theme==='dark'?'light':'dark'});render();}
async function loadRemote(){if(!backend.configured()||!backend.user()||!accessChecked)return;const owner=backend.user().id,epoch=accountEpoch;await backend.refreshSession();await subjectCatalog.load();await loadAbout();if(subject!=='All subjects'&&!subjectCatalog.names().includes(subject))subject='All subjects';if(!focusRunning&&!subjectCatalog.names().includes(focusSubject))focusSubject=subjectCatalog.names()[0]||'';const types={lectureNotes:null,materials:'materials',lectures:'lectures',cases:'cases',flashcards:null,quizSets:'quiz_sets',quizQuestions:'quiz_questions'};const results=await Promise.allSettled(Object.entries(types).map(async([key,table])=>{const responses=await Promise.allSettled([table?backend.read(table):Promise.resolve([]),backend.cloudRead(key)]);const data=responses.filter(r=>r.status==='fulfilled').flatMap((r,i)=>r.value.map(x=>({...x,lexamah_cloud:r===responses[1]})));if(responses.every(r=>r.status==='rejected'))throw responses[0].reason;if(epoch!==accountEpoch||backend.user()?.id!==owner)return;remote[key]=data.map(x=>({...x,title:x.title||x.name,subject:x.subject||x.course||'General',body:x.body||x.content||x.summary,url:x.url||x.file_url||x.recording_url}));}));if(epoch!==accountEpoch||backend.user()?.id!==owner)return;render();const failures=results.filter(x=>x.status==='rejected');if(failures.length)toast(`${failures.length} content tables could not load. Local resources are available; check Supabase permissions and schema.`);return failures;}
function bindForms(){if($('#search'))$('#search').oninput=ev=>{filter=ev.target.value;const start=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);};if($('#subject'))$('#subject').onchange=ev=>{subject=ev.target.value;flashIndex=0;flashBack=false;render();};if($('#task-form'))$('#task-form').onsubmit=ev=>{ev.preventDefault();const text=new FormData(ev.target).get('task').trim();if(!text)return;store.update({tasks:[...store.get().tasks,{id:crypto.randomUUID(),text,done:false}]});render();};if($('#profile-form'))$('#profile-form').onsubmit=async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(event.target));const profile={...store.get().profile,name:values.name.trim(),phone_number:values.phone_number.trim(),institution:values.institution.trim(),level:values.level.trim()};if(!profile.name)return;await backend.saveProfile(profile);store.update({profile});render();toast('Profile updated.');}catch(err){toast(err.message);}};if($('#config-form'))$('#config-form').onsubmit=async ev=>{ev.preventDefault();try{if(!backend.adminReady())throw new Error('Administrator access required.');const f=new FormData(ev.target);backend.configure(f.get('url'),f.get('key'));await loadRemote();toast('Configuration saved. Check loaded content and sign in below.');}catch(err){toast(err.message);}};if($('#signup-form'))$('#signup-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('button[type="submit"],button:not([type])'),status=$('#signup-status');submit.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));const profile={phone_number:values.phone_number.trim(),full_name:values.full_name.trim(),username:values.username.trim(),institution:values.institution.trim(),level:values.level.trim()};if(Object.values(profile).some(value=>!value))throw new Error('Complete every signup field.');if(!/^\+?[0-9 ()-]{7,25}$/.test(profile.phone_number))throw new Error('Enter a valid phone number.');status.textContent='Creating your account…';const result=await backend.signUp(values.email.trim(),values.password,profile);if(result.access_token){await activateAccount();trackVisit();await loadRemote();location.hash='dashboard';toast('Your account is ready.');}else{location.hash='login';toast('Check your email to confirm your account, then log in with your username.');}}catch(err){status.textContent=err.message.includes('Database error saving new user')?'Your account could not be created. Check that the latest SQL is installed and try a different username.':err.message;}finally{submit.disabled=false;}};if($('#login-form'))$('#login-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('button[type="submit"],button:not([type])'),status=$('#login-status');submit.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));status.textContent='Logging in…';await flushProgress().catch(()=>{});await backend.signIn(values.username.trim(),values.password);await activateAccount();trackVisit();await loadRemote();location.hash='dashboard';toast('Welcome back.');}catch(err){status.textContent=err.message;}finally{submit.disabled=false;}};if($('#import-data'))$('#import-data').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>5e6)throw new Error('Please choose a backup smaller than 5 MB.');store.import(await file.text());render();toast('Backup imported.');}catch(err){toast(err.message);}};if($('#focus-subject'))$('#focus-subject').onchange=ev=>focusSubject=ev.target.value;if($('#focus-length'))$('#focus-length').onchange=ev=>{focusSeconds=Number(ev.target.value)*60;focusRemaining=focusSeconds;render();};}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,[data-route]');if(!b)return;try{
if(backend.adminReady()&&await adminClick(b))return;
if(!backend.user()&&!['menu','sidebar-close','theme','close-dialog'].includes(b.id)&&!b.dataset.route)return;
if(b.dataset.route==='admin'&&!backend.adminReady()){location.hash='dashboard';return;}
if(b.dataset.route){location.hash=b.dataset.route;if(route===b.dataset.route)navigate();}
if(b.dataset.readingKind){materialKind=b.dataset.readingKind;render();}
if(b.dataset.openResource){const [type,id]=b.dataset.openResource.split(':');await openResource(type,id);}
if(b.dataset.downloadResource){const [type,id]=b.dataset.downloadResource.split(':');const item=resourceById(type,id);if(item)requestDownload({...item,resource_type:type});}
if(b.dataset.playRecording){const item=recordings().find(x=>x.id===b.dataset.playRecording);if(item)await playRecording(item);}
if(b.dataset.bookmark){store.toggle('bookmarks',b.dataset.bookmark);render();toast('Saved resources updated.');}
if(b.dataset.openMaterial)await openResource('materials',b.dataset.openMaterial);if(b.dataset.openCase)await openResource('cases',b.dataset.openCase);
if(b.dataset.create)createForm(b.dataset.create);if(b.dataset.edit){const [type,id]=b.dataset.edit.split(':');createForm(type,id);}if(b.dataset.delete){const [type,id]=b.dataset.delete.split(':');modal('Delete this resource?',`<p class="muted">This removes the resource from your browser library${type==='quizSets'?' and its questions':''}. Export a backup from Settings if you want to retain a copy.</p><div class="actions"><button class="btn danger" id="confirm-delete">Delete resource</button><button class="btn" id="cancel-delete">Keep resource</button></div>`);$('#cancel-delete').onclick=()=>$('#dialog').close();$('#confirm-delete').onclick=()=>{const patch={[type]:store.get()[type].filter(x=>x.id!==id)};if(type==='quizSets')patch.quizQuestions=store.get().quizQuestions.filter(x=>x.quiz_set_id!==id);store.update(patch);$('#dialog').close();render();toast('Resource deleted.');};}
if(b.dataset.removeTask){ev.preventDefault();store.update({tasks:store.get().tasks.filter(t=>t.id!==b.dataset.removeTask)});render();}
if(b.dataset.startQuiz){const set=list('quizSets').find(q=>q.id===b.dataset.startQuiz);quiz={set,questions:list('quizQuestions').filter(q=>q.quiz_set_id===set.id),index:0,answers:[],end:Date.now()+(Number(set.time_minutes)||10)*60000,finished:false};clearInterval(quizTimer);quizTimer=setInterval(()=>{if(!quiz||quiz.finished)return;const left=Math.max(0,Math.ceil((quiz.end-Date.now())/1000));if($('#quiz-clock'))$('#quiz-clock').textContent=time(left);if(!left)finishQuiz();},500);render();}
if(b.dataset.answer!==undefined&&quiz&&!quiz.finished&&!quiz.advancing){const active=quiz;active.answers[active.index]=Number(b.dataset.answer);active.advancing=true;render();await new Promise(resolve=>setTimeout(resolve,200));if(quiz===active&&!active.finished){active.advancing=false;if(active.index<active.questions.length-1){active.index++;render();}else await finishQuiz();}}
const id=b.id;
if(id==='sidebar-close'){$('#sidebar').classList.remove('open');sidebarCollapsed=true;localStorage.setItem('lexamah:sidebar-collapsed','true');$('#menu').setAttribute('aria-expanded','false');updateSidebar();return;}
if(id==='menu'){if(window.matchMedia('(max-width:900px)').matches){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));}else{sidebarCollapsed=!sidebarCollapsed;localStorage.setItem('lexamah:sidebar-collapsed',String(sidebarCollapsed));updateSidebar();}return;}
if(id==='theme'||id==='settings-theme')toggleTheme();if(id==='close-dialog')$('#dialog').close();
if(id==='quiz-next'&&quiz&&!quiz.advancing){quiz.index++;render();}if(id==='quiz-prev'&&quiz&&!quiz.advancing){quiz.index--;render();}if(id==='quiz-finish')await finishQuiz();if(id==='quiz-reset'){quiz=null;render();}if(id==='quiz-exit'){modal('Leave this quiz?',`<p class="muted">Your unfinished answers will not be saved.</p><div class="actions"><button class="btn danger" id="confirm-exit">Leave quiz</button><button class="btn" id="keep-quiz">Keep going</button></div>`);$('#keep-quiz').onclick=()=>$('#dialog').close();$('#confirm-exit').onclick=()=>{clearInterval(quizTimer);quiz=null;$('#dialog').close();render();};}
if(id==='flip-card'){flashBack=!flashBack;render();}if(id==='flash-next'||id==='flash-prev'){const n=filtered(list('flashcards')).length;flashIndex=(flashIndex+(id==='flash-next'?1:-1)+n)%n;flashBack=false;render();}
if(id==='focus-toggle'){if(focusRunning){focusRemaining=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));focusRunning=false;clearInterval(focusTimer);}else{focusRunning=true;focusEnd=Date.now()+focusRemaining*1000;focusTimer=setInterval(()=>{focusRemaining=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));if($('#focus-clock'))$('#focus-clock').textContent=time(focusRemaining);if(!focusRemaining){saveFocus();}},500);}render();}
if(id==='focus-reset'){clearInterval(focusTimer);focusRunning=false;focusRemaining=focusSeconds;render();}if(id==='focus-end')saveFocus();
if(id==='export-data')download('lexamah-backup.json',store.export(),'application/json');if(id==='sign-out'){await flushProgress().catch(()=>{});try{await backend.signOut();}finally{resetWorkspace(null);location.hash='login';render();}toast('Signed out.');}
}catch(err){toast(err.message||'This action could not be completed.');}});
document.addEventListener('change',ev=>{if(!backend.user())return;if(ev.target.dataset.task){store.update({tasks:store.get().tasks.map(t=>t.id===ev.target.dataset.task?{...t,done:ev.target.checked}:t)});render();}});
$('#dialog').addEventListener('click',ev=>{if(ev.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#dialog').close();}});
window.addEventListener('hashchange',navigate);window.addEventListener('beforeunload',ev=>{if(focusRunning||(quiz&&!quiz.finished)){ev.preventDefault();ev.returnValue='';}});
initAdmin({render,toast,modal,reload:loadRemote});
initAudio({toast});initDownloads({toast,modal});
document.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));function resetWorkspace(id){accountEpoch++;resetAdmin();clearInterval(quizTimer);clearInterval(focusTimer);quiz=null;focusRunning=false;focusRemaining=focusSeconds;flashIndex=0;flashBack=false;remote={};stopAudio();closeReader();if($('#dialog').open)$('#dialog').close();pauseSync();store.useAccount(id);accessChecked=false;}
function updateSidebar(){const mobile=window.matchMedia('(max-width:900px)').matches;document.body.classList.toggle('sidebar-collapsed',!mobile&&sidebarCollapsed);if(!mobile)$('#menu').setAttribute('aria-expanded',String(!sidebarCollapsed));}
async function activateAccount(){const id=backend.user()?.id;resetWorkspace(id);if(!id)return;await backend.resolveAccess();if(backend.user()?.id!==id)return;await backend.loadProfile();if(backend.user()?.id!==id)return;accessChecked=true;applyAccountProfile();await syncAccount({render,toast});}
async function refreshAccess(){if(accessFlight)return accessFlight;accessFlight=(async()=>{const id=backend.user()?.id;if(!id||backend.recoveryReady())return;try{await backend.resolveAccess();if(backend.user()?.id!==id){resetWorkspace(null);location.hash='login';}render();}catch(err){if(!backend.user()){resetWorkspace(null);location.hash='login';render();}else if(route==='admin'){route='dashboard';render();}toast(err.message);}})().finally(()=>accessFlight=null);return accessFlight;}
window.addEventListener('resize',updateSidebar);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshAccess();});
setInterval(()=>{if(document.visibilityState!=='hidden')refreshAccess();},60000);
async function start(){await handleRecoveryLink();try{if(backend.user()&&!backend.recoveryReady())await activateAccount();else resetWorkspace(null);}catch(err){backend.clearSession();resetWorkspace(null);toast(err.message);}navigate();trackVisit();if(backend.user()&&!backend.recoveryReady())loadRemote().catch(err=>toast(err.message));else loadAbout().then(render);}
$('#sidebar').insertAdjacentHTML('afterbegin','<button id="sidebar-close" class="icon-button" aria-label="Collapse navigation">×</button>');
start();
